LANDING_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Move conference programs from open call to published agenda with SessionBuddy.">\n  <title>SessionBuddy · Conference program management</title>\n  <link rel="icon" href="/landing/assets/sessionbuddy-favicon.svg" type="image/svg+xml">\n  <link rel="stylesheet" href="/landing/assets/landing.css?v=14">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=27">\n  <script src="/app-shell/assets/api-client.js?v=10" defer></script>\n  <script src="/app-shell/assets/app-shell.js?v=35" defer></script>\n  <script src="/landing/assets/demo-access.js?v=3" defer></script>\n</head>\n<body class="marketing-page">\n  <a class="skip-link" href="#main">Skip to main content</a>\n  <header class="site-header">\n    <div class="page-shell nav-row">\n      <a class="brand" href="/" aria-label="SessionBuddy home">\n        <svg class="brand-mark" viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="sb-brand-g" x1="0" y1="0" x2="64" y2="64" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#8B3FF5"/><stop offset="1" stop-color="#5D8CFF"/></linearGradient></defs><rect width="64" height="64" rx="16" fill="url(#sb-brand-g)"/><g fill="none" stroke-width="6" stroke-linecap="round"><path d="M16 20V44" stroke="#FFFFFF"/><path d="M30 20H43" stroke="#C9D3FF"/><path d="M30 32H48" stroke="#FFFFFF"/><path d="M30 44H43" stroke="#C9D3FF"/></g></svg>\n        <span>SessionBuddy</span>\n      </a>\n      <nav class="primary-nav" aria-label="Primary navigation">\n        <span data-landing-account><a class="nav-action" href="/sign-in?redirect=%2Fadmin">Sign in</a></span>\n      </nav>\n    </div>\n  </header>\n\n  <main id="main" class="marketing-main" tabindex="-1">\n    <section class="hero" aria-labelledby="hero-title">\n      <div class="page-shell hero-grid">\n        <div class="hero-copy">\n          <p class="eyebrow">Conference program management</p>\n          <h1 id="hero-title">From open call to published agenda.</h1>\n          <p class="hero-lede">Collect proposals, run reviews, prepare speakers, and publish the program from one workspace.</p>\n          <div class="hero-actions"><a class="button button-primary" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in to manage a program</a></div>\n        </div>\n\n        <aside class="agenda-card" aria-labelledby="agenda-title">\n          <div class="agenda-heading"><strong id="agenda-title">AI Engineer NYC · Program desk</strong><span>Oct 12</span></div>\n          <ol class="agenda-list">\n            <li><time datetime="09:00">09:00</time><div><strong>Opening keynote</strong><span>Main hall · Program preview</span></div><i class="track track-orange" aria-hidden="true"></i></li>\n            <li><time datetime="10:15">10:15</time><div><strong>Building reliable AI systems</strong><span>Engineering track · Hall A</span></div><i class="track track-blue" aria-hidden="true"></i></li>\n            <li><time datetime="11:30">11:30</time><div><strong>Code agents in production</strong><span>Agents track · Studio B</span></div><i class="track track-green" aria-hidden="true"></i></li>\n          </ol>\n        </aside>\n      </div>\n    </section>\n\n    <section class="workflow-section" aria-labelledby="workflow-title">\n      <div class="page-shell workflow-layout">\n        <div class="workflow-heading">\n          <p class="eyebrow">One connected workflow</p>\n          <h2 id="workflow-title">Keep the program moving.</h2>\n          <p>Everyone works from the same event record, from the first proposal to the published schedule.</p>\n        </div>\n        <ol class="workflow-steps">\n          <li><span>01</span><div><h3>Collect</h3><p>Open the call and receive structured proposals.</p></div></li>\n          <li><span>02</span><div><h3>Review</h3><p>Assign reviewers and make decisions with context.</p></div></li>\n          <li><span>03</span><div><h3>Prepare</h3><p>Coordinate speaker tasks, files, and communication.</p></div></li>\n          <li><span>04</span><div><h3>Publish</h3><p>Build the agenda and share the finished program.</p></div></li>\n        </ol>\n      </div>\n    </section>\n\n    <section class="demo-section" data-demo-panel aria-labelledby="demo-section-title" hidden>\n      <div class="page-shell demo-layout">\n        <div class="demo-heading">\n          <p class="eyebrow">Explore the workspace</p>\n          <h2 id="demo-section-title">Try it from every seat.</h2>\n          <p>Enter a sample workspace instantly. No password or setup required.</p>\n        </div>\n        <div data-demo-access></div>\n      </div>\n    </section>\n\n    <section class="public-programs-section" aria-labelledby="public-programs-title">\n      <div class="page-shell">\n        <div class="public-programs-heading">\n          <h2 id="public-programs-title">Explore events</h2>\n          <p>Open calls, schedules, and speakers.</p>\n        </div>\n        <div data-public-events class="public-events-grid" aria-busy="true">\n          <p class="public-events-empty" role="status">Loading public events…</p>\n        </div>\n        <div class="featured-heading featured-heading--compact">\n          <div><p class="eyebrow">Featured</p><h3 id="featured-title">AI Engineer conferences</h3></div>\n          <p>Upcoming programs supported by SessionBuddy.</p>\n        </div>\n        <div class="featured-grid">\n          <article class="featured-event event-new-york" aria-labelledby="featured-nyc-title">\n            <div class="event-content"><p class="event-brand">AI Engineer <span>New York</span></p><p class="event-meta">Oct 12–14 · New York <span>Planning</span></p><h3 id="featured-nyc-title">AI Engineer New York 2026</h3><p>Program setup, submissions, and speaker preparation in one event workspace.</p><a href="https://www.ai.engineer/nyc/2026">Explore event <span aria-hidden="true">→</span></a></div>\n          </article>\n          <article class="featured-event event-code" aria-labelledby="featured-code-title">\n            <div class="event-content"><p class="event-brand code-brand">AI Engineer <span>Code Summit</span></p><p class="event-meta">Nov 10–12 · San Francisco <span>Application only</span></p><h3 id="featured-code-title">AI Engineer Code 2026</h3><p>A dedicated code conference coming home to Silicon Valley.</p><a href="https://www.ai.engineer/code/2026">Explore event <span aria-hidden="true">→</span></a></div>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section class="closing-section" aria-labelledby="closing-title">\n      <div class="page-shell closing-card"><div><p class="eyebrow">One program, one workspace</p><h2 id="closing-title">Ready to move your conference forward?</h2></div><a class="button button-primary" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in to manage a program</a></div>\n    </section>\n  </main>\n\n  <footer><div class="page-shell footer-row"><span>SessionBuddy</span><nav aria-label="Project and contact links"><a href="https://github.com/gachchami/sessionbuddy" target="_blank" rel="noopener noreferrer">GitHub <span aria-hidden="true">↗</span></a><a href="https://x.com/imkin" target="_blank" rel="noopener noreferrer">X / @imkin <span aria-hidden="true">↗</span></a><a href="mailto:me@dbhanushali.com">me@dbhanushali.com</a></nav></div></footer>\n</body>\n</html>\n'

